WITH RECURSIVE walk AS (SELECT id AS leaf_id, id AS current_id, canonical_image_id AS next_id, 0 AS depth FROM public.product_images WHERE canonical_image_id IS NOT NULL UNION ALL SELECT w.leaf_id, w.next_id, pi.canonical_image_id, w.depth + 1 FROM walk w JOIN public.product_images pi ON pi.id = w.next_id WHERE pi.canonical_image_id IS NOT NULL AND w.depth < 10), roots AS (SELECT leaf_id, current_id AS root_id, MAX(depth) AS max_depth FROM walk WHERE next_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = walk.next_id AND p.canonical_image_id IS NOT NULL) GROUP BY leaf_id, current_id) UPDATE public.product_images pi SET canonical_image_id = r.root_id, last_modified_source = 'claude', updated_at = now() FROM roots r WHERE pi.id = r.leaf_id AND pi.id <> r.root_id AND r.max_depth > 0;;
